sys_script_include.script:
var DataRequest = Class.create();
DataRequest.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	/**
     * Reference Qualifier for 'handled_by' field on Data Request table.
     * Returns staff records (x_2223823_apollo_0_staff) whose associated user has the 'compliance_officer' role.
     */
    getHandledByRefQual: function(current) {
        var staffSysids = [];

        // 1. Pehle sys_user_has_role table se un users ko nikalo jinke paas 'compliance_officer' role hai
        var userSysids = [];
        var roleGr = new GlideRecord('sys_user_has_role');
        roleGr.addQuery('role.name', 'x_2223823_apollo_0.compliance_officer'); // Role ka exact role name 
        roleGr.addQuery('state', 'active'); // Ensure role is active
        roleGr.query();

        while (roleGr.next()) {
            var userId = roleGr.getValue('user');
            if (userId) {
                userSysids.push(userId);
            }
        }

        // 2. Agar compliance officers mil gaye, toh staff table me query karo jahan staff.user in userSysids ho
        if (userSysids.length > 0) {
            var staffGr = new GlideRecord('x_2223823_apollo_0_staff');
            staffGr.addQuery('user', 'IN', userSysids.join(','));
            staffGr.query();

            while (staffGr.next()) {
                staffSysids.push(staffGr.getUniqueValue());
            }
        }

        // 3. Final Query String Return karo
        if (staffSysids.length > 0) {
            return 'sys_idIN' + staffSysids.join(',');
        } else {
            // Agar koi compliance officer staff nahi mila toh empty result dikhao
            return 'sys_id=00000000000000000000000000000000';
        }
    },

    type: 'DataRequest'
});
